+  void fill_words(Register base, Register cnt, Register value, Register tmp,
+                  bool is_large, VectorRegister Vtmp = Z_V0);

@@ -10292,1 +10292,2 @@
-  predicate(((ClearArrayNode*)n)->requires_word_fill());
+  predicate(((ClearArrayNode*)n)->requires_word_fill() &&
+            !((ClearArrayNode*)n)->is_large());
@@ -10297,1 +10298,12 @@
-  ins_encode %{ __ fill_words($base$$Register, $cnt$$Register, $val$$Register, $tmpL$$Register); %}
+  ins_encode %{ __ fill_words($base$$Register, $cnt$$Register, $val$$Register, $tmpL$$Register, false); %}
+  ins_pipe(pipe_class_dummy);
+%}
+
+instruct inlineCallClearArrayWordFillBig(iRegL cnt, iRegP_N2P base, iRegL val, Universe dummy, iRegL tmpL, v16TempReg v16, flagsReg cr) %{
+  predicate(((ClearArrayNode*)n)->requires_word_fill() &&
+            ((ClearArrayNode*)n)->is_large());
+  match(Set dummy (ClearArray (Binary cnt base) val));
+  effect(TEMP tmpL, TEMP v16, KILL cr);
+  ins_cost(BRANCH_COST); // dynamic-length store loop
+  format %{ "ClearArrayWordCopy $cnt,$base,$val" %}
+  ins_encode %{ __ fill_words($base$$Register, $cnt$$Register, $val$$Register, $tmpL$$Register, true, $v16$$VectorRegister); %}
